bg=1
motifs={3:[[3,1,3],[3,1,3],[3,3,3]],9:[[1,1,9],[1,9,9],[9,1,9]],8:[[8,8,8],[1,8,1],[8,8,8]]}
g=[[bg]*7 for _ in range(19)]
for k,(color,motif) in enumerate(motifs.items()):
    r0=1+k*6
    for r in range(r0,r0+5):
        for c in range(1,6): g[r][c]=color
    for i in range(3):
        for j in range(3):
            if motif[i][j]==color: g[r0+1+i][2+j]=bg
print('\n'.join(' '.join(map(str,row)) for row in g))
